solution.solution.c:
#include <stdbool.h>
#include <stdlib.h>

typedef struct node {
    int value;
    struct node *next;
} Node;

bool push_front(Node **head, int value)
{
    Node *n = malloc(sizeof *n);
    if (n == NULL) return false;
    n->value = value;
    n->next = *head;
    *head = n;
    return true;
}

bool push_back(Node **head, int value)
{
    Node **link = head;
    while (*link != NULL) link = &(*link)->next;
    Node *n = malloc(sizeof *n);
    if (n == NULL) return false;
    n->value = value;
    n->next = NULL;
    *link = n;
    return true;
}

size_t length(const Node *head)
{
    size_t count = 0;
    for (const Node *n = head; n != NULL; n = n->next) count++;
    return count;
}

bool remove_value(Node **head, int value)
{
    for (Node **link = head; *link != NULL; link = &(*link)->next) {
        if ((*link)->value == value) {
            Node *gone = *link;
            *link = gone->next;
            free(gone);
            return true;
        }
    }
    return false;
}

void reverse(Node **head)
{
    Node *previous = NULL;
    Node *current = *head;
    while (current != NULL) {
        Node *next = current->next;
        current->next = previous;
        previous = current;
        current = next;
    }
    *head = previous;
}

void free_list(Node **head)
{
    Node *n = *head;
    while (n != NULL) {
        Node *next = n->next;
        free(n);
        n = next;
    }
    *head = NULL;
}

unitTests:
TEST("pushing onto the front") { Node *list = NULL; CHECK_EQ(length(list), (size_t)0); push_front(&list, 3); push_front(&list, 2); push_front(&list, 1); CHECK_EQ(length(list), (size_t)3); CHECK_EQ(list->value, 1); CHECK_EQ(list->next->value, 2); CHECK_EQ(list->next->next->value, 3); CHECK(list->next->next->next == NULL); free_list(&list); CHECK(list == NULL); }
TEST("pushing onto the back") { Node *list = NULL; push_back(&list, 1); push_back(&list, 2); push_back(&list, 3); CHECK_EQ(list->value, 1); CHECK_EQ(list->next->next->value, 3); CHECK(list->next->next->next == NULL); free_list(&list); }
TEST("removing values") { Node *list = NULL; for (int i = 1; i <= 5; i++) push_back(&list, i); CHECK(remove_value(&list, 1)); CHECK_EQ(list->value, 2); CHECK(remove_value(&list, 5)); CHECK(remove_value(&list, 3)); CHECK(!remove_value(&list, 3)); CHECK_EQ(length(list), (size_t)2); CHECK_EQ(list->value, 2); CHECK_EQ(list->next->value, 4); remove_value(&list, 2); remove_value(&list, 4); CHECK(list == NULL); CHECK(!remove_value(&list, 4)); }
TEST("reversing in place") { Node *list = NULL; for (int i = 1; i <= 4; i++) push_back(&list, i); Node *first = list; reverse(&list); CHECK_EQ(list->value, 4); CHECK_EQ(list->next->value, 3); CHECK_EQ(list->next->next->value, 2); CHECK(list->next->next->next == first); CHECK(first->next == NULL); free_list(&list); Node *empty = NULL; reverse(&empty); CHECK(empty == NULL); }
TEST("a long list") { Node *list = NULL; for (int i = 0; i < 5000; i++) push_front(&list, i); CHECK_EQ(length(list), (size_t)5000); CHECK_EQ(list->value, 4999); free_list(&list); CHECK_EQ(length(list), (size_t)0); }

